{
  "packet_id": "H6-T04-3",
  "claim_id": "C018",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C018.component",
    "value": "When evidence supports intentional waiting, a need to simplify setup should not be assumed.",
    "scope": "A restriction on interpretation in the intentional-waiting branch, not a conclusion that simplification could never help.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span directly supplies the conditional restriction on assuming setup needs simplification."
    }
  },
  "signal_basis": {
    "component_id": "C018.signal_basis",
    "value": "A customer states a future roster date and subsequently publishes around that date without setup assistance, supporting deliberate delay. The mapping proposes this observation rather than reporting an established finding.",
    "scope": "Evidence for intentional waiting in the observed customer; it does not establish that setup obstacles are absent.",
    "provenance": {
      "refs": [
        {
          "source_id": "P018",
          "role": "SUPPORT"
        },
        {
          "source_id": "P020",
          "role": "SUPPORT"
        },
        {
          "source_id": "P003",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited spans supply the timing-and-publication pattern, its proposed status, and the qualification that mechanisms may coexist."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C018.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "The claim is supported within its explicit bounds; no unresolved empirical relation is required for this judgment."
    }
  },
  "rationale": "Assuming the described signal occurs, deliberate timing provides an explanation for delayed publication without establishing a need to simplify setup. This licenses withholding that assumption while leaving open whether simplification could help.",
  "uncertainty": "Intentional waiting may coexist with setup difficulties. The claim preserves that uncertainty and makes no exclusion or prevalence claim.",
  "anomalies": []
}
